#[inline]
fn destack_display_window_event_close_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    handle: resource::WindowEventHandle,
) -> RuntimeResult<()> {
    let _ = &handle;

    binding.replay().run_binding_without_context(
        DISPLAY_WINDOW_EVENT_CLOSE,
        binding.replay_payload_for(DISPLAY_WINDOW_EVENT_CLOSE)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_display_window_event_close(binding, handle)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_display_window_event_close(binding, handle)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = DisplayWindowEventCloseReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(ReplayError::from(error.as_ref()));
                    DisplayWindowEventCloseReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

#[inline]
fn destack_display_window_event_open_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut resource::WindowEventHandle,
    options: WindowEventOpenOptions,
) -> RuntimeResult<()> {
    let _ = &options;

    binding.replay().run_binding_without_context(
        DISPLAY_WINDOW_EVENT_OPEN,
        binding.replay_payload_for(DISPLAY_WINDOW_EVENT_OPEN)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_display_window_event_open(binding, out, options)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_display_window_event_open(binding, out, options)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded = result_value;
                let payload = DisplayWindowEventOpenReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(ReplayError::from(error.as_ref()));
                    DisplayWindowEventOpenReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native = value;
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

