#[inline]
fn destack_display_window_focus_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    window: resource::WindowHandle,
) -> RuntimeResult<()> {
    let _ = &window;

    binding.replay().run_binding_without_context(
        DISPLAY_WINDOW_FOCUS,
        binding.replay_payload_for(DISPLAY_WINDOW_FOCUS)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_display_window_focus(binding, window)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_display_window_focus(binding, window)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = DisplayWindowFocusReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(ReplayError::from(error.as_ref()));
                    DisplayWindowFocusReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

