#[inline]
fn destack_display_window_state_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    window: resource::WindowHandle,
) -> RuntimeResult<vm::Value> {
    let result = binding.replay().run_binding(
        DISPLAY_WINDOW_STATE,
        binding.replay_payload_for(DISPLAY_WINDOW_STATE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_display_window_state(binding, context, window)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_display_window_state(binding, context, window)
            }
        },
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value: WindowStateVm = value.clone();
                let result_recorded_backend = result_value.backend;
                let result_recorded_position_x = result_value.position.x;
                let result_recorded_position_y = result_value.position.y;
                let result_recorded_position = WindowPosition {
                    x: result_recorded_position_x,
                    y: result_recorded_position_y,
                };
                let result_recorded_size_logical_width = result_value.size_logical.width;
                let result_recorded_size_logical_height = result_value.size_logical.height;
                let result_recorded_size_logical = WindowLogicalSize {
                    width: result_recorded_size_logical_width,
                    height: result_recorded_size_logical_height,
                };
                let result_recorded_size_physical_width = result_value.size_physical.width;
                let result_recorded_size_physical_height = result_value.size_physical.height;
                let result_recorded_size_physical = WindowPhysicalSize {
                    width: result_recorded_size_physical_width,
                    height: result_recorded_size_physical_height,
                };
                let result_recorded_scale_factor_milli = result_value.scale_factor_milli;
                let result_recorded_visibility = result_value.visibility;
                let result_recorded_display = if let Some(value) = result_value.display {
                    let result_recorded_display_inner = value;
                    Some(result_recorded_display_inner)
                } else {
                    None
                };
                let result_recorded_focused = result_value.focused;
                let result_recorded_occlusion = result_value.occlusion;
                let result_recorded_safe_area_insets =
                    if let Some(value) = result_value.safe_area_insets {
                        let result_recorded_safe_area_insets_inner_left_px = value.left_px;
                        let result_recorded_safe_area_insets_inner_top_px = value.top_px;
                        let result_recorded_safe_area_insets_inner_right_px = value.right_px;
                        let result_recorded_safe_area_insets_inner_bottom_px = value.bottom_px;
                        let result_recorded_safe_area_insets_inner = WindowSafeAreaInsets {
                            left_px: result_recorded_safe_area_insets_inner_left_px,
                            top_px: result_recorded_safe_area_insets_inner_top_px,
                            right_px: result_recorded_safe_area_insets_inner_right_px,
                            bottom_px: result_recorded_safe_area_insets_inner_bottom_px,
                        };
                        Some(result_recorded_safe_area_insets_inner)
                    } else {
                        None
                    };
                let result_recorded_theme = result_value.theme;
                let result_recorded_chrome = result_value.chrome;
                let result_recorded_taskbar_visible = result_value.taskbar_visible;
                let result_recorded_opacity = result_value.opacity;
                let result_recorded_always_on_top = result_value.always_on_top;
                let result_recorded_parent = if let Some(value) = result_value.parent {
                    let result_recorded_parent_inner = value;
                    Some(result_recorded_parent_inner)
                } else {
                    None
                };
                let result_recorded_transient_for = if let Some(value) = result_value.transient_for
                {
                    let result_recorded_transient_for_inner = value;
                    Some(result_recorded_transient_for_inner)
                } else {
                    None
                };
                let result_recorded_modal = result_value.modal;
                let result_recorded_mouse_passthrough = result_value.mouse_passthrough;
                let result_recorded_aspect_ratio = if let Some(value) = result_value.aspect_ratio {
                    let result_recorded_aspect_ratio_inner_numerator = value.numerator;
                    let result_recorded_aspect_ratio_inner_denominator = value.denominator;
                    let result_recorded_aspect_ratio_inner = WindowAspectRatio {
                        numerator: result_recorded_aspect_ratio_inner_numerator,
                        denominator: result_recorded_aspect_ratio_inner_denominator,
                    };
                    Some(result_recorded_aspect_ratio_inner)
                } else {
                    None
                };
                let result_recorded = WindowState {
                    backend: result_recorded_backend,
                    position: result_recorded_position,
                    size_logical: result_recorded_size_logical,
                    size_physical: result_recorded_size_physical,
                    scale_factor_milli: result_recorded_scale_factor_milli,
                    visibility: result_recorded_visibility,
                    display: result_recorded_display,
                    focused: result_recorded_focused,
                    occlusion: result_recorded_occlusion,
                    safe_area_insets: result_recorded_safe_area_insets,
                    theme: result_recorded_theme,
                    chrome: result_recorded_chrome,
                    taskbar_visible: result_recorded_taskbar_visible,
                    opacity: result_recorded_opacity,
                    always_on_top: result_recorded_always_on_top,
                    parent: result_recorded_parent,
                    transient_for: result_recorded_transient_for,
                    modal: result_recorded_modal,
                    mouse_passthrough: result_recorded_mouse_passthrough,
                    aspect_ratio: result_recorded_aspect_ratio,
                };
                let payload = DisplayWindowStateReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(ReplayError::from(error.as_ref()));
                    DisplayWindowStateReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result_backend = value.backend;
                    let vm_result_position_x = value.position.x;
                    let vm_result_position_y = value.position.y;
                    let vm_result_position = WindowPositionVm {
                        x: vm_result_position_x,
                        y: vm_result_position_y,
                    };
                    let vm_result_size_logical_width = value.size_logical.width;
                    let vm_result_size_logical_height = value.size_logical.height;
                    let vm_result_size_logical = WindowLogicalSizeVm {
                        width: vm_result_size_logical_width,
                        height: vm_result_size_logical_height,
                    };
                    let vm_result_size_physical_width = value.size_physical.width;
                    let vm_result_size_physical_height = value.size_physical.height;
                    let vm_result_size_physical = WindowPhysicalSizeVm {
                        width: vm_result_size_physical_width,
                        height: vm_result_size_physical_height,
                    };
                    let vm_result_scale_factor_milli = value.scale_factor_milli;
                    let vm_result_visibility = value.visibility;
                    let vm_result_display = if let Some(value) = value.display {
                        let vm_result_display_inner = value;
                        Some(vm_result_display_inner)
                    } else {
                        None
                    };
                    let vm_result_focused = value.focused;
                    let vm_result_occlusion = value.occlusion;
                    let vm_result_safe_area_insets = if let Some(value) = value.safe_area_insets {
                        let vm_result_safe_area_insets_inner_left_px = value.left_px;
                        let vm_result_safe_area_insets_inner_top_px = value.top_px;
                        let vm_result_safe_area_insets_inner_right_px = value.right_px;
                        let vm_result_safe_area_insets_inner_bottom_px = value.bottom_px;
                        let vm_result_safe_area_insets_inner = WindowSafeAreaInsetsVm {
                            left_px: vm_result_safe_area_insets_inner_left_px,
                            top_px: vm_result_safe_area_insets_inner_top_px,
                            right_px: vm_result_safe_area_insets_inner_right_px,
                            bottom_px: vm_result_safe_area_insets_inner_bottom_px,
                        };
                        Some(vm_result_safe_area_insets_inner)
                    } else {
                        None
                    };
                    let vm_result_theme = value.theme;
                    let vm_result_chrome = value.chrome;
                    let vm_result_taskbar_visible = value.taskbar_visible;
                    let vm_result_opacity = value.opacity;
                    let vm_result_always_on_top = value.always_on_top;
                    let vm_result_parent = if let Some(value) = value.parent {
                        let vm_result_parent_inner = value;
                        Some(vm_result_parent_inner)
                    } else {
                        None
                    };
                    let vm_result_transient_for = if let Some(value) = value.transient_for {
                        let vm_result_transient_for_inner = value;
                        Some(vm_result_transient_for_inner)
                    } else {
                        None
                    };
                    let vm_result_modal = value.modal;
                    let vm_result_mouse_passthrough = value.mouse_passthrough;
                    let vm_result_aspect_ratio = if let Some(value) = value.aspect_ratio {
                        let vm_result_aspect_ratio_inner_numerator = value.numerator;
                        let vm_result_aspect_ratio_inner_denominator = value.denominator;
                        let vm_result_aspect_ratio_inner = WindowAspectRatioVm {
                            numerator: vm_result_aspect_ratio_inner_numerator,
                            denominator: vm_result_aspect_ratio_inner_denominator,
                        };
                        Some(vm_result_aspect_ratio_inner)
                    } else {
                        None
                    };
                    let vm_result = WindowStateVm {
                        backend: vm_result_backend,
                        position: vm_result_position,
                        size_logical: vm_result_size_logical,
                        size_physical: vm_result_size_physical,
                        scale_factor_milli: vm_result_scale_factor_milli,
                        visibility: vm_result_visibility,
                        display: vm_result_display,
                        focused: vm_result_focused,
                        occlusion: vm_result_occlusion,
                        safe_area_insets: vm_result_safe_area_insets,
                        theme: vm_result_theme,
                        chrome: vm_result_chrome,
                        taskbar_visible: vm_result_taskbar_visible,
                        opacity: vm_result_opacity,
                        always_on_top: vm_result_always_on_top,
                        parent: vm_result_parent,
                        transient_for: vm_result_transient_for,
                        modal: vm_result_modal,
                        mouse_passthrough: vm_result_mouse_passthrough,
                        aspect_ratio: vm_result_aspect_ratio,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_display_window_state_result(context, result)?;
    Ok(result)
}

